<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'; import { useRoute } from 'vue-router'; import { http, errorMessage } from '../../api/http'; import type { Order } from '../../types'; import { money, dateTime } from '../../utils/format'; import StatusBadge from '../../components/StatusBadge.vue'; import LoadingState from '../../components/LoadingState.vue'; import ConfirmDialog from '../../components/ConfirmDialog.vue'
const route = useRoute(), admin = computed(() => route.path.startsWith('/admin')), order = ref<Order>(), loading = ref(true), busy = ref(false), error = ref(''), success = ref(''), confirm = ref(false); const base = computed(() => admin.value ? '/admin/orders' : '/orders'); const payable = computed(() => order.value?.orderStatus === 'Pending' && order.value?.paymentStatus !== 'Paid');
async function load() { loading.value = true; try { order.value = (await http.get<Order>(`${base.value}/${route.params.id}`)).data } catch (e) { error.value = errorMessage(e) } finally { loading.value = false } }
async function action(type: string) { if (busy.value) return; busy.value = true; error.value = ''; success.value = ''; confirm.value = false; try { let data: Order; if (admin.value) data = (await http.patch<Order>(`${base.value}/${route.params.id}/status`, { status: type })).data; else if (type === 'Cancelled') data = (await http.post<Order>(`/orders/${route.params.id}/cancel`)).data; else data = (await http.post<Order>(`/orders/${route.params.id}/simulate-payment`, { success: type === 'Paid' })).data; order.value = data; success.value = 'Đã cập nhật đơn hàng.' } catch (e) { error.value = errorMessage(e); await load() } finally { busy.value = false } } onMounted(load)
</script>
<template><div :class="admin ? '' : 'container page'"><RouterLink :to="admin ? '/admin/orders' : '/orders'" class="text-link">← Danh sách đơn hàng</RouterLink><LoadingState v-if="loading" /><p v-if="error" class="alert error" role="alert">{{ error }}</p><p v-if="success" class="alert success" role="status">{{ success }}</p><template v-if="order && !loading"><div class="section-heading"><div><h1>{{ route.path.endsWith('/payment') ? 'Thanh toán giả lập' : 'Chi tiết đơn hàng' }}</h1><p class="muted">{{ order.orderCode }} · {{ dateTime(order.createdAt) }} (VN)</p></div><div class="actions"><StatusBadge :status="order.orderStatus" /><StatusBadge :status="order.paymentStatus" /></div></div><section v-if="!admin && route.path.endsWith('/payment')" class="payment-state" :class="{ 'is-paid': order.paymentStatus === 'Paid', 'is-failed': order.paymentStatus === 'Failed' }" aria-live="polite"><h2>{{ order.paymentStatus === 'Paid' ? '✓ Thanh toán thành công' : order.paymentStatus === 'Failed' ? 'Thanh toán chưa thành công' : order.orderStatus === 'Cancelled' ? 'Đơn hàng đã hủy' : 'Chờ thanh toán giả lập' }}</h2><p>{{ order.orderCode }} · Tổng tiền {{ money(order.totalAmount) }}</p><p v-if="order.paymentStatus === 'Failed' && payable">Bạn có thể thử lại bằng các nút mô phỏng bên dưới. Không có tiền thật được giao dịch.</p><RouterLink :to="`/orders/${order.id}`" class="text-link">Xem chi tiết đơn hàng →</RouterLink></section><ol v-if="order.orderStatus !== 'Cancelled'" class="order-progress" aria-label="Tiến trình đơn hàng"><li v-for="(step, index) in [{ code: 'Pending', label: 'Đang xử lý' }, { code: 'Shipping', label: 'Đang giao' }, { code: 'Completed', label: 'Hoàn thành' }]" :key="step.code" :class="{ current: order.orderStatus === step.code, done: ['Pending', 'Shipping', 'Completed'].indexOf(order.orderStatus) > index }" :aria-current="order.orderStatus === step.code ? 'step' : undefined">{{ step.label }}</li></ol><div class="checkout-grid"><section><div class="panel"><h2>Sách đã đặt</h2><article v-for="i in order.items" :key="i.productId" class="order-item"><div><RouterLink :to="`/products/${i.productId}`"><strong>{{ i.productNameSnapshot }}</strong></RouterLink><small>{{ i.skuSnapshot }} · {{ money(i.unitPrice) }} × {{ i.quantity }}</small></div><strong>{{ money(i.lineTotal) }}</strong></article><div class="summary-total"><span>Giao hàng: {{ money(order.shippingFee) }}</span><strong>Tổng {{ money(order.totalAmount) }}</strong></div></div><div class="panel"><h2>Thông tin nhận hàng</h2><p><strong>{{ order.recipientName }}</strong> · {{ order.recipientPhone }}</p><p>{{ order.shippingAddress }}</p><p v-if="order.note">Ghi chú: {{ order.note }}</p></div></section><aside class="summary-card"><h2>{{ admin ? 'Xử lý đơn' : 'Thanh toán & trạng thái' }}</h2><p>Đây là thanh toán giả lập. Không nhập thông tin thẻ hoặc ngân hàng.</p><template v-if="!admin && payable"><button class="btn full" :disabled="busy" @click="action('Paid')">Mô phỏng thành công</button><button class="btn secondary full" :disabled="busy" @click="action('Failed')">Mô phỏng thất bại</button></template><button v-if="payable" class="btn danger full" :disabled="busy" @click="confirm = true">Hủy đơn & hoàn tồn</button><template v-if="admin"><button v-if="order.orderStatus === 'Pending' && order.paymentStatus === 'Paid'" class="btn full" :disabled="busy" @click="action('Shipping')">Chuyển sang đang giao</button><button v-if="order.orderStatus === 'Shipping'" class="btn full" :disabled="busy" @click="action('Completed')">Xác nhận hoàn thành</button></template><p v-if="order.paymentStatus === 'Paid'" class="alert success">Đã thanh toán. Không hỗ trợ hủy hoặc hoàn tiền trong đồ án.</p><p v-if="order.orderStatus === 'Cancelled'" class="alert">Đơn đã hủy, tồn kho đã được hoàn.</p><small>Giá hiển thị được lưu tại thời điểm đặt hàng.</small></aside></div></template><ConfirmDialog :open="confirm" title="Xác nhận hủy đơn?" message="Đơn đang xử lý chưa thanh toán sẽ bị hủy và hoàn tồn đúng một lần." @close="confirm = false" @confirm="action('Cancelled')" /></div></template>